// open PrimeFaces dropdown
export async function openPFDropdown(triggerObj: any) {
	let panelOpen: any = new TestObject('pfPanelOpen')
	panelOpen.addProperty("xpath", ConditionType.EQUALS,
		"//div[contains(@class,'ui-selectonemenu-panel') and contains(@style,'display: block')]"
	)

	await c(triggerObj, 20)
	await WebUI.delay(0.3)

	if (!await WebUI.waitForElementVisible(panelOpen, 1, FailureHandling.OPTIONAL)) {
		await c(triggerObj, 20)
		await WebUI.delay(0.3)
		await WebUI.waitForElementVisible(panelOpen, 3, FailureHandling.OPTIONAL)
	}
}

// click dropdown option
export async function clickPFOptionByIndex(index0: any) {
	let opt: any = new TestObject("pfOpt_" + index0)
	opt.addProperty("xpath", ConditionType.EQUALS,
		`(//div[contains(@class,'ui-selectonemenu-panel') and contains(@style,'display: block')]//li[contains(@class,'ui-selectonemenu-item')])[${index0 + 1}]`
	)

	await c(opt, 20)
	await WebUI.delay(0.2)
	await waitBlockUI(20)
}

// universal dropdown select
export async function selectDropdownByIndex(dropdownObj: any, indexFromData: any) {

	let idx0: any = await toInt(indexFromData)

	for (let attempt = 0; attempt < 3; attempt++) {
		try {
			await wVisible(dropdownObj, 20)
			let el: any = await WebUiCommonHelper.findWebElement(dropdownObj, 10)
			let tag: any = await el.getTagName()

			if (tag != null && tag.equalsIgnoreCase("select")) {
				await WebUI.selectOptionByIndex(dropdownObj, idx0)
				await WebUI.delay(0.3)
				await waitBlockUI(20)
			} else {
				await openPFDropdown(dropdownObj)
				await clickPFOptionByIndex(idx0)
			}
			return

		} catch (e: any) {
			await WebUI.delay(0.5)
		}
	}

	gAssert(false, "Dropdown failed: " + dropdownObj.getObjectId())
}

// claim document
export async function claimDocument(targetDocNo: any) {

	let found: any = false

	for (let pageIndex = 1; pageIndex <= 10; pageIndex++) {

		let targetRow: any = new TestObject("targetRow_" + targetDocNo)
		targetRow.addProperty("xpath", ConditionType.EQUALS,
			"//tbody[contains(@id,'taskListGroupId_data')]//tr[td[normalize-space()='" + targetDocNo + "']]"
		)

		if (await WebUI.verifyElementPresent(targetRow, 3, FailureHandling.OPTIONAL)) {

			let claimBtn: any = new TestObject("claimBtn_" + targetDocNo)
			claimBtn.addProperty("xpath", ConditionType.EQUALS,
				"//tbody[contains(@id,'taskListGroupId_data')]//tr[td[normalize-space()='" + targetDocNo + "']]//span[normalize-space()='Claim']/ancestor::button"
			)

			await c(claimBtn, 20)
			await waitBlockUI(30)
			await WebUI.delay(1)

			found = true
			break
		}

		if (pageIndex < 10) {
			let nextIndex: any = pageIndex + 1

			let nextPage: any = new TestObject("page_" + nextIndex)
			nextPage.addProperty("xpath", ConditionType.EQUALS,
				"(//span[contains(@class,'ui-paginator-pages')]/span[normalize-space()='" + nextIndex + "'])[1]"
			)

			if (await WebUI.verifyElementPresent(nextPage, 5, FailureHandling.OPTIONAL)) {
				await WebUI.scrollToElement(nextPage, 3)
				await WebUI.click(nextPage)
				await waitBlockUI(30)
				await WebUI.delay(1)
			} else {
				break
			}
		}
	}

	return found
}
